import { useEffect, useState } from 'react';
import './AdminDashboard.css';
import api from '../../api';

export default function AdminDashboard({ currentUser, onLogout }) {
  const [activeTab, setActiveTab] = useState('create');
  const [assignments, setAssignments] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [loadError, setLoadError] = useState('');

  // Form State
  const [title, setTitle] = useState('');
  const [language, setLanguage] = useState('JavaScript');
  const [description, setDescription] = useState('');
  const [deadline, setDeadline] = useState('');
  const [posting, setPosting] = useState(false);

  // Rating Modal State
  const [selectedSubmission, setSelectedSubmission] = useState(null);
  const [selectedRating, setSelectedRating] = useState('5');
  const [saving, setSaving] = useState(false);

  const loadAssignments = () => {
    api
      .listAssignments()
      .then(setAssignments)
      .catch((err) => setLoadError(err.message || 'Failed to load assignments'));
  };

  const loadSubmissions = () => {
    api
      .listSubmissions()
      .then(setSubmissions)
      .catch((err) => setLoadError(err.message || 'Failed to load submissions'));
  };

  useEffect(() => {
    loadAssignments();
    loadSubmissions();
  }, []);

  const handlePostAssignment = async (e) => {
    e.preventDefault();

    if (!title.trim() || !description.trim() || !deadline) {
      alert('Please fill in all required fields.');
      return;
    }

    setPosting(true);
    try {
      await api.createAssignment({
        title: title.trim(),
        language,
        description: description.trim(),
        deadline
      });

      alert(`Assignment "${title}" posted successfully!`);

      setTitle('');
      setLanguage('JavaScript');
      setDescription('');
      setDeadline('');
      loadAssignments();
    } catch (err) {
      alert(err.message || 'Failed to post assignment');
    } finally {
      setPosting(false);
    }
  };

  const openRatingModal = (submission) => {
    setSelectedSubmission(submission);
    setSelectedRating(submission.rating ? String(submission.rating) : '5');
  };

  const closeRatingModal = () => {
    setSelectedSubmission(null);
    setSelectedRating('5');
  };

  const handleSaveRating = async () => {
    if (!selectedSubmission) return;

    const ratingValue = parseFloat(selectedRating);
    setSaving(true);
    try {
      await api.rateSubmission(selectedSubmission.id, ratingValue);
      alert(`Rating of ${ratingValue}/5 saved for ${selectedSubmission.student_name || 'Student'}!`);
      closeRatingModal();
      loadSubmissions();
    } catch (err) {
      alert(err.message || 'Failed to save rating');
    } finally {
      setSaving(false);
    }
  };

  const pendingSubmissionsCount = submissions.filter((s) => s.rating === null || s.rating === undefined).length;

  return (
    <div className="dashboard-container">
      {/* Header */}
      <header className="dashboard-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h1 className="dashboard-title">⚡ Admin Dashboard</h1>
          <p className="dashboard-subtitle">
            Manage coursework assignments and evaluate student code submissions seamlessly.
          </p>
        </div>
        {onLogout && (
          <button className="btn-secondary" onClick={onLogout} style={{ whiteSpace: 'nowrap', padding: '0.6rem 1.2rem' }}>
            🚪 Log Out
          </button>
        )}
      </header>

      {/* Navigation */}
      <nav className="dashboard-nav" aria-label="Admin Navigation">
        <button
          className={`nav-button ${activeTab === 'create' ? 'active' : ''}`}
          onClick={() => setActiveTab('create')}
        >
          ➕ Post New Assignment
        </button>

        <button
          className={`nav-button ${activeTab === 'submissions' ? 'active' : ''}`}
          onClick={() => setActiveTab('submissions')}
        >
          📥 Check Submissions
          {pendingSubmissionsCount > 0 && (
            <span className="badge-count" aria-label={`${pendingSubmissionsCount} pending submissions`}>
              {pendingSubmissionsCount} Pending
            </span>
          )}
        </button>
      </nav>

      {loadError && <div className="error-banner" style={{ margin: '1rem 0' }}>{loadError}</div>}

      {/* Tab 1: Create Assignment */}
      {activeTab === 'create' && (
        <section>
          <div className="card">
            <h2 className="section-heading">Create New Assignment</h2>
            <form onSubmit={handlePostAssignment}>
              <div className="form-group">
                <label className="form-label" htmlFor="assignment-title">Assignment Title</label>
                <input
                  id="assignment-title"
                  className="form-input"
                  type="text"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                  placeholder="e.g. Python Functions & Modules"
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="programming-language">Programming Language</label>
                <select
                  id="programming-language"
                  className="form-select"
                  value={language}
                  onChange={(e) => setLanguage(e.target.value)}
                >
                  <option value="JavaScript">JavaScript</option>
                  <option value="Python">Python</option>
                  <option value="Java">Java</option>
                  <option value="C#">C#</option>
                  <option value="C++">C++</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="assignment-description">Description & Requirements</label>
                <textarea
                  id="assignment-description"
                  className="form-textarea"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Provide comprehensive details and coding instructions for students..."
                />
              </div>

              <div className="form-group">
                <label className="form-label" htmlFor="submission-deadline">Submission Deadline</label>
                <input
                  id="submission-deadline"
                  className="form-input"
                  type="date"
                  value={deadline}
                  onChange={(e) => setDeadline(e.target.value)}
                />
              </div>

              <button type="submit" className="btn-primary" disabled={posting}>
                {posting ? 'Posting…' : '+ Post Assignment'}
              </button>
            </form>
          </div>

          <div>
            <h3 className="section-heading">Posted Assignments ({assignments.length})</h3>
            {assignments.length === 0 ? (
              <div className="card" style={{ textAlign: 'center', color: 'var(--text-muted)' }}>
                No assignments posted yet. Use the form above to add your first assignment.
              </div>
            ) : (
              <div className="card-list">
                {assignments.map((item) => (
                  <div key={item.id} className="submission-card">
                    <div className="card-header-row">
                      <strong style={{ fontSize: '1.05rem', color: 'var(--text-primary)' }}>{item.title}</strong>
                      <span className="language-badge">{item.language}</span>
                    </div>
                    <p style={{ color: 'var(--text-secondary)', fontSize: '0.925rem', margin: '8px 0 12px 0' }}>
                      {item.description}
                    </p>
                    <div className="date-text">📅 Deadline: {item.deadline}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </section>
      )}

      {/* Tab 2: Check Submissions */}
      {activeTab === 'submissions' && (
        <section>
          <h2 className="section-heading">Student Code Submissions</h2>
          {submissions.length === 0 ? (
            <div className="card" style={{ textAlign: 'center', color: 'var(--text-muted)' }}>
              No student submissions available for evaluation yet.
            </div>
          ) : (
            <div className="card-list">
              {submissions.map((item) => (
                <article key={item.id} className="submission-card">
                  <div className="card-header-row">
                    <div className="meta-group">
                      <span className="student-name">👤 {item.student_name}</span>
                      <span className="language-badge">{item.language}</span>
                    </div>
                    <span className="date-text">
                      Submitted: {item.submitted_at ? item.submitted_at.split('T')[0] : 'N/A'}
                    </span>
                  </div>

                  <div style={{ margin: '8px 0', fontSize: '0.95rem' }}>
                    <strong>Assignment:</strong> {item.assignment_title}
                  </div>

                  <div className="code-block-container">
                    <div className="code-block-label">Submitted Code</div>
                    <pre className="code-block">
                      <code>{item.code || '// No code submitted.'}</code>
                    </pre>
                  </div>

                  <div className="card-header-row" style={{ marginTop: '16px', marginBottom: 0 }}>
                    <div>
                      <strong style={{ fontSize: '0.9rem', color: 'var(--text-secondary)' }}>Rating: </strong>
                      {item.rating !== null && item.rating !== undefined ? (
                        <span className="rating-display">★ {item.rating} / 5</span>
                      ) : (
                        <span className="rating-none">Not Rated</span>
                      )}
                    </div>

                    <button
                      className="btn-action"
                      onClick={() => openRatingModal(item)}
                    >
                      {item.rating !== null && item.rating !== undefined ? 'Update Rating' : 'Rate Assignment'}
                    </button>
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>
      )}

      {/* Rating Evaluation Modal */}
      {selectedSubmission && (
        <div className="modal-overlay" role="dialog" aria-modal="true">
          <div className="modal-container">
            <h3 className="modal-header">Rate Submission</h3>
            <div className="modal-body">
              <div className="modal-info-row">
                <strong>Student:</strong> {selectedSubmission.student_name}
              </div>
              <div className="modal-info-row">
                <strong>Assignment:</strong> {selectedSubmission.assignment_title}
              </div>

              <div className="form-group" style={{ marginTop: '20px' }}>
                <label className="form-label" htmlFor="rating-select">Select Rating (1 to 5 Stars):</label>
                <select
                  id="rating-select"
                  className="form-select"
                  value={selectedRating}
                  onChange={(e) => setSelectedRating(e.target.value)}
                >
                  <option value="5">★★★★★ (5 / 5)</option>
                  <option value="4">★★★★☆ (4 / 5)</option>
                  <option value="3">★★★☆☆ (3 / 5)</option>
                  <option value="2">★★☆☆☆ (2 / 5)</option>
                  <option value="1">★☆☆☆☆ (1 / 5)</option>
                </select>
              </div>
            </div>

            <div className="modal-footer">
              <button className="btn-secondary" onClick={closeRatingModal}>
                Cancel
              </button>
              <button className="btn-primary" onClick={handleSaveRating} disabled={saving}>
                {saving ? 'Saving…' : 'Save Rating'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
